begin;
select plan(16);
select ok(not has_table_privilege('authenticated','public.profile_preferences','UPDATE'),'preferences cannot be edited directly');
select ok(not has_function_privilege('anon','public.update_my_profile(integer,text,text,text,text,text[],text,uuid)','EXECUTE'),'anonymous edit denied');
set local role authenticated;
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000003';
select is(public.update_my_profile(0,'Consumidor Local',null,'Gosto de doces','Turma A',array['Chocolate','Cookie'],'profile-create','99000000-0000-4000-8000-000000000001')->>'revision','1','own profile saved');
select is(public.update_my_profile(0,'Consumidor Local',null,'Gosto de doces','Turma A',array['Chocolate','Cookie'],'profile-create','99000000-0000-4000-8000-000000000002')->>'revision','1','idempotent replay before version validation');
select throws_ok($$select public.update_my_profile(0,'Outro nome',null,'','',array[]::text[],'profile-create','99000000-0000-4000-8000-000000000001')$$,'P0001','IDEMPOTENCY_CONFLICT','same key different payload rejected');
select throws_ok($$select public.update_my_profile(0,'Outro nome',null,'','',array[]::text[],'profile-stale','99000000-0000-4000-8000-000000000001')$$,'P0001','PROFILE_REVISION_CONFLICT','stale revision rejected');
select throws_ok($$select public.update_my_profile(1,'Outro nome','10000000-0000-4000-8000-000000000001/99000000-0000-4000-8000-000000000001.webp','','',array[]::text[],'profile-photo','99000000-0000-4000-8000-000000000001')$$,'22023','INVALID_PROFILE_PHOTO','another user photo rejected');
select throws_ok($$select public.update_my_profile(1,'Outro nome',null,'','',array['Chocolate','Chocolate'],'profile-duplicate','99000000-0000-4000-8000-000000000001')$$,'22023','INVALID_PROFILE','duplicate interests rejected');
select throws_ok($$select public.update_my_profile(1,'Outro nome',null,'','',array['unknown'],'profile-unknown','99000000-0000-4000-8000-000000000001')$$,'22023','INVALID_PROFILE','unknown interests rejected');
select is((select revision from public.profile_preferences),1,'rejected writes preserve revision');
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000001';
select is((select count(*)::integer from public.profile_preferences),0,'administrator cannot read another person private interests');
reset role;
select is((select count(*)::integer from public.audit_logs where action='profile.updated'),1,'replays create no duplicate audit');
select ok(not exists(select 1 from public.audit_logs where action='profile.updated' and (metadata ? 'bio' or metadata ? 'preferences')),'audit omits personal interests');
update public.profiles set active=false where id='10000000-0000-4000-8000-000000000003';
set local role authenticated;
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000003';
select throws_ok($$select public.update_my_profile(1,'Outro nome',null,'','',array[]::text[],'profile-disabled','99000000-0000-4000-8000-000000000001')$$,'42501','PROFILE_EDIT_FORBIDDEN','inactive session cannot edit');
reset role;
update public.profiles set active=true where id='10000000-0000-4000-8000-000000000003';
set local role authenticated;
set local "request.jwt.claim.sub" = '10000000-0000-4000-8000-000000000003';
select is(public.update_my_profile(1,'Consumidor Local',null,'','',array[]::text[],'profile-clear','99000000-0000-4000-8000-000000000001')->>'revision','2','optional fields can be cleared');
select is((select bio || class_name || array_to_string(sweet_preferences,',') from public.profile_preferences),'','clear persists');
select * from finish();
rollback;
